=طلب تواصل من عميل
الاسم: {{ $json.customer_name }}
الموبايل: {{ $json.customer_phone }}
الحجز رقم {{ $json.id }} بتاريخ {{ String($json.booking_date).slice(0, 10) }} الساعة {{ String($json.booking_time).slice(0, 5) }}
حالة الدفع: {{ $json.payment_status }}

parameters.jsCode:
const rows = $input.all().map(i => i.json).filter(r => r && r.booking_time && r.booking_date && String(r.status || 'confirmed').toLowerCase() !== 'cancelled');
const taken = {};
for (const r of rows) {
  const d = String(r.booking_date).slice(0, 10);
  (taken[d] = taken[d] || new Set()).add(String(r.booking_time).slice(0, 5));
}
const cairo = new Date(new Date().toLocaleString('en-US', { timeZone: 'Africa/Cairo' }));
const pad = n => String(n).padStart(2, '0');
const nowMin = cairo.getHours() * 60 + cairo.getMinutes();
const days = ['الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'];
const fmt = h => h === 12 ? '12:00 ظهرًا' : ((h % 12) + ':00 ' + (h < 12 ? 'ص' : 'م'));
const lines = ['Generated now at ' + pad(cairo.getHours()) + ':' + pad(cairo.getMinutes()) + ' Cairo time. This list is fresh and overrides anything said earlier in the conversation.'];
for (let k = 0; k < 14; k++) {
  const dt = new Date(cairo.getFullYear(), cairo.getMonth(), cairo.getDate() + k);
  const d = dt.getFullYear() + '-' + pad(dt.getMonth() + 1) + '-' + pad(dt.getDate());
  const label = days[dt.getDay()] + (k === 0 ? ' - النهاردة' : k === 1 ? ' - بكرة' : '');
  const set = taken[d] || new Set();
  const free = [];
  const booked = [];
  for (let h = 10; h < 18; h++) {
    const code = pad(h) + ':00';
    if (set.has(code)) { booked.push(fmt(h)); continue; }
    if (k === 0 && h * 60 <= nowMin) continue;
    free.push(fmt(h) + ' (code ' + code + ')');
  }
  lines.push(d + ' ' + label + '\n  FREE: ' + (free.length ? free.join(' | ') : 'NO FREE TIMES') + '\n  TAKEN: ' + (booked.length ? booked.join(' | ') : 'none'));
}
// Active upcoming bookings that belong to THIS Telegram account (the customer's own data only)
const chatId = String($('Telegram Trigger').first().json.message?.chat?.id ?? '');
const normPhone = p => String(p || '').replace(/[\s-]/g, '');
const mine = rows.filter(r => String(r.customer_chat_id || '') === chatId);
const others = rows.filter(r => String(r.customer_chat_id || '') !== chatId).map(r => ({ phone: normPhone(r.customer_phone) }));
const myLines = mine.length
  ? mine.map(r => 'id ' + r.id + ' | name: ' + r.customer_name + ' | phone: ' + r.customer_phone + ' | ' + String(r.booking_date).slice(0, 10) + ' ' + String(r.booking_time).slice(0, 5) + ' | service_id ' + r.service_id + ' | status ' + r.status + ' | payment ' + r.payment_status + ' | deposit ' + r.deposit_amount).join('\n')
  : 'none';
return [{ json: { availability: lines.join('\n'), chat_id: chatId, my_bookings: myLines, mine: mine.map(r => ({ name: r.customer_name, phone: normPhone(r.customer_phone) })), others } }];

// Escape characters Telegram's HTML parser rejects, and respect the 4096-char limit
const out = String($input.first().json.output ?? '').trim();
const safe = out.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fallback = 'عذراً، ممكن توضحلي طلبك أكتر؟ / Sorry, could you rephrase that?';
return [{ json: { reply: (safe || fallback).slice(0, 4000) } }];

parameters.text:
=شكرًا لاختيارك عيادة نور دنتيست.
تفاصيل حجزك:

رقم الحجز: {{ $('Get Just-Confirmed Booking').first().json.id }}
الخدمة: {{ (() => { const n = String($json.name || ''); const i = n.indexOf('('); const j = n.indexOf(')'); return (i > -1 && j > i) ? n.slice(i + 1, j) : (n || 'غير محدد'); })() }}
السعر: {{ $json.price ?? '-' }} جنيه
المبلغ المطلوب سداده (العربون): {{ $('Get Just-Confirmed Booking').first().json.deposit_amount }} جنيه
التاريخ: {{ (() => { const b = $('Get Just-Confirmed Booking').first().json; const days = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت']; const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر']; const p = String(b.booking_date).slice(0, 10).split('-').map(Number); const wd = new Date(Date.UTC(p[0], p[1] - 1, p[2])).getUTCDay(); return days[wd] + ' ' + p[2] + ' ' + months[p[1] - 1]; })() }}
الساعة: {{ (() => { const b = $('Get Just-Confirmed Booking').first().json; const h = parseInt(String(b.booking_time).slice(0, 2)); const m = String(b.booking_time).slice(3, 5); const suffix = h === 12 ? 'ظهرًا' : (h > 12 ? 'م' : 'ص'); return ((h % 12) || 12) + ':' + m + ' ' + suffix; })() }}

وفقًا لسياسة العيادة، يتم تثبيت الحجز نهائيًا بعد سداد المبلغ المطلوب. يمكنك اختيار الإجراء المناسب من الأزرار أدناه، ويسعدنا خدمتك دائمًا.
